       (SELECT count(*) FROM task t WHERE t.board_id = b.id) AS cards,
       (SELECT count(*) FROM task t WHERE t.board_id = b.id AND t.conversation_id IS NOT NULL) AS chats
  FROM board b ORDER BY b.name;

